using Npgsql;
using Shared.Primitives.Identifiers;

namespace Core.Identity;

public sealed class NpgsqlMobileSessionService(NpgsqlDataSource dataSource, TimeProvider clock, SessionPolicy policy) : IMobileSessionService
{
    public async Task<MobileSessionContext?> CreateAsync(Identity identity, Membership membership, DateTimeOffset? mfaVerifiedAt = null, CancellationToken cancellationToken = default)
    {
        if (identity.Status != IdentityStatus.Active || membership.Status != MembershipStatus.Active || identity.TenantId != membership.TenantId) return null;
        var now = clock.GetUtcNow(); var id = Guid.CreateVersion7(); var expires = now.Add(policy.MobileSessionLifetime);
        await using var connection = await dataSource.OpenConnectionAsync(cancellationToken); await using var transaction = await connection.BeginTransactionAsync(cancellationToken); await SetTenantAsync(connection, transaction, membership.TenantId, cancellationToken);
        await using var command = new NpgsqlCommand("insert into platform.mobile_session (id, tenant_id, identity_id, membership_id, created_at, expires_at, security_stamp, mfa_verified_at, status) values ($1, $2, $3, $4, $5, $6, $7, $8, 'Active')", connection, transaction); command.Parameters.AddWithValue(id); command.Parameters.AddWithValue(membership.TenantId.Value); command.Parameters.AddWithValue(identity.Id.Value); command.Parameters.AddWithValue(membership.Id.Value); command.Parameters.AddWithValue(now); command.Parameters.AddWithValue(expires); command.Parameters.AddWithValue(identity.SecurityStamp); command.Parameters.AddWithValue((object?)mfaVerifiedAt ?? DBNull.Value); await command.ExecuteNonQueryAsync(cancellationToken); await transaction.CommitAsync(cancellationToken); return new MobileSessionContext(identity.Id, membership.Id, membership.TenantId, now, expires, identity.SecurityStamp, id, mfaVerifiedAt);
    }
    public async Task<MobileSessionContext?> LoadAsync(Guid sessionId, IdentityId identityId, TenantId tenantId, CancellationToken cancellationToken = default)
    {
        try { await using var connection = await dataSource.OpenConnectionAsync(cancellationToken); await using var transaction = await connection.BeginTransactionAsync(cancellationToken); await SetTenantAsync(connection, transaction, tenantId, cancellationToken); await using var command = new NpgsqlCommand("select s.membership_id, s.created_at, s.expires_at, s.security_stamp, s.mfa_verified_at from platform.mobile_session s join platform.identity i on i.tenant_id=s.tenant_id and i.id=s.identity_id join platform.membership m on m.tenant_id=s.tenant_id and m.id=s.membership_id and m.identity_id=s.identity_id where s.id=$1 and s.tenant_id=$2 and s.identity_id=$3 and s.status='Active' and s.expires_at>now() and s.security_stamp=i.security_stamp and i.status='Active' and m.status='Active' limit 1", connection, transaction); command.Parameters.AddWithValue(sessionId); command.Parameters.AddWithValue(tenantId.Value); command.Parameters.AddWithValue(identityId.Value); await using var reader = await command.ExecuteReaderAsync(System.Data.CommandBehavior.SingleRow, cancellationToken); if (!await reader.ReadAsync(cancellationToken)) return null; var result = new MobileSessionContext(identityId, new MembershipId(reader.GetGuid(0)), tenantId, reader.GetFieldValue<DateTimeOffset>(1), reader.GetFieldValue<DateTimeOffset>(2), reader.GetGuid(3), sessionId, reader.IsDBNull(4) ? null : reader.GetFieldValue<DateTimeOffset>(4)); await reader.DisposeAsync(); await transaction.CommitAsync(cancellationToken); return result; } catch (NpgsqlException) when (!cancellationToken.IsCancellationRequested) { return null; }
    }
    public async Task<bool> ValidateAsync(Guid sessionId, IdentityId identityId, TenantId tenantId, Guid securityStamp, CancellationToken cancellationToken = default) => (await LoadAsync(sessionId, identityId, tenantId, cancellationToken)) is { } session && session.SecurityStamp == securityStamp;
    public async Task<bool> MarkMfaVerifiedAsync(Guid sessionId, IdentityId identityId, TenantId tenantId, DateTimeOffset verifiedAt, CancellationToken cancellationToken = default) { await using var connection = await dataSource.OpenConnectionAsync(cancellationToken); await using var transaction = await connection.BeginTransactionAsync(cancellationToken); await SetTenantAsync(connection, transaction, tenantId, cancellationToken); await using var command = new NpgsqlCommand("update platform.mobile_session set mfa_verified_at=$4 where id=$1 and tenant_id=$2 and identity_id=$3 and status='Active' and expires_at>$4", connection, transaction); command.Parameters.AddWithValue(sessionId); command.Parameters.AddWithValue(tenantId.Value); command.Parameters.AddWithValue(identityId.Value); command.Parameters.AddWithValue(verifiedAt); var result = await command.ExecuteNonQueryAsync(cancellationToken) == 1; await transaction.CommitAsync(cancellationToken); return result; }
    public async Task<bool> RevokeAsync(Guid sessionId, TenantId tenantId, CancellationToken cancellationToken = default) { await using var connection = await dataSource.OpenConnectionAsync(cancellationToken); await using var transaction = await connection.BeginTransactionAsync(cancellationToken); await SetTenantAsync(connection, transaction, tenantId, cancellationToken); await using var command = new NpgsqlCommand("update platform.mobile_session set status='Revoked', revoked_at=now(), revoked_reason='logout' where id=$1 and tenant_id=$2 and status='Active'", connection, transaction); command.Parameters.AddWithValue(sessionId); command.Parameters.AddWithValue(tenantId.Value); var result = await command.ExecuteNonQueryAsync(cancellationToken) == 1; await transaction.CommitAsync(cancellationToken); return result; }
    public async Task RevokeAsync(IdentityId identityId, CancellationToken cancellationToken = default) { await using var connection = await dataSource.OpenConnectionAsync(cancellationToken); await using var transaction = await connection.BeginTransactionAsync(cancellationToken); await using var resolve = new NpgsqlCommand("select tenant_id from platform.identity where id=$1 limit 1", connection, transaction); resolve.Parameters.AddWithValue(identityId.Value); var tenant = await resolve.ExecuteScalarAsync(cancellationToken); if (tenant is not Guid tenantId) return; await SetTenantAsync(connection, transaction, new TenantId(tenantId), cancellationToken); await using var command = new NpgsqlCommand("update platform.mobile_session set status='Revoked', revoked_at=now(), revoked_reason='identity_revoke' where tenant_id=$1 and identity_id=$2 and status='Active'", connection, transaction); command.Parameters.AddWithValue(tenantId); command.Parameters.AddWithValue(identityId.Value); await command.ExecuteNonQueryAsync(cancellationToken); await transaction.CommitAsync(cancellationToken); }
    private static async Task SetTenantAsync(NpgsqlConnection connection, NpgsqlTransaction transaction, TenantId tenantId, CancellationToken cancellationToken) { await using var command = new NpgsqlCommand("select set_config('app.tenant_id',$1,true)", connection, transaction); command.Parameters.AddWithValue(tenantId.Value.ToString("D")); await command.ExecuteNonQueryAsync(cancellationToken); }
}

public sealed class MobileSessionService(TimeProvider clock, SessionPolicy policy) : IMobileSessionService
{
    private readonly Dictionary<Guid, MobileSessionContext> sessions = []; private readonly HashSet<IdentityId> revokedIdentities = []; private readonly object gate = new();
    public Task<MobileSessionContext?> CreateAsync(Identity identity, Membership membership, DateTimeOffset? mfaVerifiedAt = null, CancellationToken cancellationToken = default) { cancellationToken.ThrowIfCancellationRequested(); if (identity.Status != IdentityStatus.Active || membership.Status != MembershipStatus.Active || identity.TenantId != membership.TenantId) return Task.FromResult<MobileSessionContext?>(null); lock (gate) { if (revokedIdentities.Contains(identity.Id)) return Task.FromResult<MobileSessionContext?>(null); var now = clock.GetUtcNow(); var result = new MobileSessionContext(identity.Id, membership.Id, membership.TenantId, now, now.Add(policy.MobileSessionLifetime), identity.SecurityStamp, Guid.CreateVersion7(), mfaVerifiedAt); sessions[result.SessionId] = result; return Task.FromResult<MobileSessionContext?>(result); } }
    public Task<MobileSessionContext?> LoadAsync(Guid sessionId, IdentityId identityId, TenantId tenantId, CancellationToken cancellationToken = default) { cancellationToken.ThrowIfCancellationRequested(); lock (gate) return Task.FromResult(sessions.TryGetValue(sessionId, out var result) && result.IdentityId == identityId && result.TenantId == tenantId && result.ExpiresAt > clock.GetUtcNow() && !revokedIdentities.Contains(identityId) ? result : null); }
    public async Task<bool> ValidateAsync(Guid sessionId, IdentityId identityId, TenantId tenantId, Guid securityStamp, CancellationToken cancellationToken = default) => (await LoadAsync(sessionId, identityId, tenantId, cancellationToken)) is { } session && session.SecurityStamp == securityStamp;
    public Task<bool> MarkMfaVerifiedAsync(Guid sessionId, IdentityId identityId, TenantId tenantId, DateTimeOffset verifiedAt, CancellationToken cancellationToken = default) { cancellationToken.ThrowIfCancellationRequested(); lock (gate) { if (!sessions.TryGetValue(sessionId, out var session) || session.IdentityId != identityId || session.TenantId != tenantId || session.ExpiresAt <= verifiedAt) return Task.FromResult(false); sessions[sessionId] = session with { MfaVerifiedAt = verifiedAt }; return Task.FromResult(true); } }
    public Task<bool> RevokeAsync(Guid sessionId, TenantId tenantId, CancellationToken cancellationToken = default) { cancellationToken.ThrowIfCancellationRequested(); lock (gate) return Task.FromResult(sessions.Remove(sessionId)); }
    public Task RevokeAsync(IdentityId identityId, CancellationToken cancellationToken = default) { cancellationToken.ThrowIfCancellationRequested(); lock (gate) { revokedIdentities.Add(identityId); foreach (var id in sessions.Where(item => item.Value.IdentityId == identityId).Select(item => item.Key).ToArray()) sessions.Remove(id); } return Task.CompletedTask; }
}
